import os
import atexit
from collections import defaultdict


class StackEnvironmentStore(object):
    """
    The purpose of this class is to map a DeploymentStack object to a list of
    created and updated environment files.

    We want to have only one instance of that class. The stack's environment
    files are updated from different places of the library (network, image,
    stack). The environments are eventually used for stack creation.

    Created files are deleted at program termination.
    """
    def __init__(self):
        self._store = defaultdict(list)

    def get_stack_environments(self, stack):
        return self._store[stack]

    def add_stack_environment(self, stack, env_file, index=None):
        if index is None:
            index = len(self._store[stack])
        return self._store[stack].insert(index, env_file)

    def clear_stack_environments(self, stack):
        self._remove_stack_environments(stack)
        self._store[stack] = []

    def remove_all_environments(self):
        for stack in self._store:
            self.clear_stack_environments(stack)

    def _remove_stack_environments(self, stack):
        for env in self._store[stack]:
            try:
                os.remove(env)
            except (TypeError, OSError):
                pass


PreparedEnvironments = StackEnvironmentStore()
atexit.register(PreparedEnvironments.remove_all_environments)
